// math 데모 전역 설정: CSRF 토큰/헤더, OCR 엔드포인트, 벤더 경로, MathLive 폰트 경로, 닮음 기호 글꼴.
// 다른 모든 글루 모듈보다 먼저 로드된다(KaTeX/MathLive/TinyMCE 다음).
(function () {
  "use strict";
  const meta = (name) => {
    const el = document.querySelector('meta[name="' + name + '"]');
    return el ? el.getAttribute("content") || "" : "";
  };
  const csrfToken = meta("_csrf");
  // CookieCsrfTokenRepository.withHttpOnlyFalse() 기본 헤더명 = X-XSRF-TOKEN (서버가 meta 로 노출)
  const csrfHeader = meta("_csrf_header") || "X-XSRF-TOKEN";

  // MathLive 폰트 자체호스팅 경로 지정 (전역 MathfieldElement 로드 뒤). 미지정 시 폰트 404. 키 입력 소리는 프론트처럼 끈다.
  if (window.MathfieldElement) {
    try {
      window.MathfieldElement.fontsDirectory = "/js/vendor/mathlive/fonts";
      window.MathfieldElement.soundsDirectory = null;
    } catch (e) {
      /* 일부 버전은 정적 setter 가 없을 수 있음 — 무시 */
    }
  }

  // 닮음 기호 ∽(\backsim)를 교과서·시안 모양(양끝이 말린 누운 S)으로 — KaTeX_AMS 기본 모양은 작은 물결이다
  // Noto Sans KR(OFL)에서 이 한 글자만 뽑은 파일. 저장되는 LaTeX는 그대로 \backsim
  // KaTeX_AMS 는 ∽ 를 이미 갖고 있어 나중에 선언된 쪽이 쓰인다. 문항 뷰어·편집기 번들이 KaTeX 글꼴을 페이지 CSS 보다 뒤에 넣으므로
  // CSS @font-face 대신, 선언 순서와 무관하게 CSS 글꼴보다 앞서는 FontFace 로 등록한다
  document.fonts.add(
    new FontFace("KaTeX_AMS", 'url("/css/fonts/NotoSansKR-similar.woff") format("woff")', {
      style: "normal",
      weight: "400",
      display: "swap",
      unicodeRange: "U+223D",
    })
  );

  window.MathConfig = {
    csrfToken: csrfToken,
    csrfHeader: csrfHeader,
    ocrEndpoint: "/api/math-ocr",
    samplesUrl: "/js/math/samples.json",
    tinymceBaseUrl: "/js/vendor/tinymce",
    // 스페이스바·가상 키보드 공백 키가 삽입하는 값. math-field 의 mathModeSpace 로 대입한다.
    // 폭을 바꾸려면 여기만 고치면 된다 (\; 두꺼운 / \: 중간 / \, 얇은 / \quad 넓은 공백).
    spaceLatex: "\\;",
    // fetch 용 CSRF 헤더 객체. FormData 전송 시 Content-Type 은 넣지 않는다(boundary 자동).
    csrfHeaders: function () {
      return csrfToken ? { [csrfHeader]: csrfToken } : {};
    },
  };
})();

// $...$ LaTeX 구분자 <-> 수식 노드 마크업 양방향 변환. (utils/mathDelimiterToTipTap.ts 직번역, server 가드 제거)
// 수식 노드 DOM 계약: 인라인 <span data-type="inline-math" data-latex>, 블록 <div data-type="block-math" data-latex>.
(function () {
  "use strict";
  const compat = window.MathCompat;

  // HTML 엔티티 디코드(수식 안의 &lt; 등을 실제 LaTeX 문자로). &amp; 는 이중 디코드 방지 위해 마지막.
  const decodeEntities = (s) =>
    s
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&quot;/g, '"')
      .replace(/&#0*39;|&apos;/g, "'")
      .replace(/&#x([0-9a-fA-F]+);/g, (_m, h) => String.fromCodePoint(parseInt(h, 16)))
      .replace(/&#(\d+);/g, (_m, d) => String.fromCodePoint(parseInt(d, 10)))
      .replace(/&amp;/g, "&");

  // LaTeX 를 data-latex 속성값으로 안전하게 이스케이프. & 먼저.
  const escapeAttr = (s) =>
    s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

  // 캡처한 LaTeX 한 조각을 수식 노드 마크업으로. 멀티라인이면 block-math, 아니면 inline-math.
  const toMathNode = (rawLatex) => {
    const decoded = decodeEntities(rawLatex);
    if (!decoded.trim()) return ""; // 공백뿐이면 무시
    const latex = compat.toKatexCompatLatex(decoded);
    const attr = escapeAttr(latex);
    return compat.isMultilineLatex(latex)
      ? '<div data-type="block-math" data-latex="' + attr + '"></div>'
      : '<span data-type="inline-math" data-latex="' + attr + '"></span>';
  };

  // $$...$$(블록) 먼저, 그다음 $...$(인라인) 치환. 주변 HTML 은 그대로 둔다.
  const latexDelimitersToHtml = (sourceHtml) => {
    if (!sourceHtml) return "";
    return sourceHtml
      .replace(/\$\$([^$]+?)\$\$/g, (_m, inner) => toMathNode(inner))
      .replace(/\$([^$]+?)\$/g, (_m, inner) => toMathNode(inner));
  };

  // (역변환) 수식 노드를 다시 $...$/$$...$$ 텍스트로 복원. 커스텀 태그는 그대로 직렬화.
  const htmlToLatexDelimiters = (html) => {
    if (!html) return html || "";
    const doc = new DOMParser().parseFromString(html, "text/html");
    doc.querySelectorAll('[data-type="block-math"]').forEach((el) => {
      el.replaceWith(doc.createTextNode("$$" + (el.getAttribute("data-latex") || "") + "$$"));
    });
    doc.querySelectorAll('[data-type="inline-math"]').forEach((el) => {
      el.replaceWith(doc.createTextNode("$" + (el.getAttribute("data-latex") || "") + "$"));
    });
    return doc.body.innerHTML;
  };

  window.MathRoundtrip = {
    latexDelimitersToHtml: latexDelimitersToHtml,
    htmlToLatexDelimiters: htmlToLatexDelimiters,
  };
})();

// 수식입력기 창 안에 그리는 키패드 정의 — 고등 PC 배치 (Figma 문제은행-디자인-최종 > 수식입력기 1744:40937)
// 프론트(douclass_exambank) utils/mathKeypadLayouts.ts 의 고등 PC 탭을 옮긴 것. CMS 는 고등 키패드 하나만 쓴다.
// label: 키 위에 그릴 LaTeX(빈칸은 \square), insert: MathLive 에 넣을 LaTeX
// insert 자리표시: #@(현재 선택 영역), #0(커서), #?(빈칸)
(function () {
  "use strict";

  // ── 키 생성 헬퍼 ──
  const k = (label, insert, opts) => Object.assign({ label: label, insert: insert == null ? label : insert }, opts || {});
  const num = (d) => k(d, d, { size: "lg" });
  const fn = (action, icon, opts) => Object.assign({ label: "", action: action, icon: icon, fn: true }, opts || {});

  const LEFT = fn("left", "left");
  const RIGHT = fn("right", "right");
  const ENTER = fn("enter", "enter");
  const BACKSPACE = fn("backspace", "backspace");

  // ── 공통 키 ──
  const PLUS = k("+", "+", { variants: [k("\\pm")] });
  const EQUAL = k("=", "=", { variants: [k("\\neq"), k("\\fallingdotseq")] });
  const CDOTS = k("\\cdots");
  const SIMILAR = k("\\backsim"); // 모양은 css/math/math-input.css 의 ∽ 글꼴
  // 평행: 시안과 교과서 표기대로 ‖ 대신 // (두 빗금을 붙여 한 기호로 묶는다)
  const PARALLEL = k("\\mathrel{/\\!\\!/}");
  const SIN = k("\\sin", "\\sin", { size: "sm" });
  const COS = k("\\cos", "\\cos", { size: "sm" });
  const TAN = k("\\tan", "\\tan", { size: "sm" });
  const SQUARE = k("\\square");
  const CIRCLE = k("\\bigcirc");
  const TRIANGLE = k("\\triangle");
  const DEGREE = k("{}^{\\circ}", "#@^{\\circ}");

  // 윗줄 (길게: 벡터 화살표 / 양방향 화살표 / 호)
  const OVERLINE = k("\\overline{\\square}", "\\overline{#@}", {
    variants: [
      k("\\overrightarrow{\\square}", "\\overrightarrow{#@}"),
      k("\\overleftrightarrow{\\square}", "\\overleftrightarrow{#@}"),
      k("\\overgroup{\\square}", "\\overgroup{#@}"),
    ],
  });

  // ── 숫자패드 (0이 두 칸) ──
  const NUMPAD = [
    [num("7"), num("8"), num("9"), LEFT],
    [num("4"), num("5"), num("6"), RIGHT],
    [num("1"), num("2"), num("3"), ENTER],
    [Object.assign(num("0"), { span: 2 }), num("."), BACKSPACE],
  ];

  // ── 연산 ──
  const OPERATORS = [
    [PLUS, k("-"), k("\\times"), k("<"), k(">")],
    [k("\\div"), EQUAL, k(":"), k("\\le"), k("\\ge")],
    [
      // 연립 (중괄호로 묶은 두 줄)
      k("\\left\\{\\begin{smallmatrix}\\square\\\\\\square\\end{smallmatrix}\\right.", "\\begin{cases}#0\\\\#?\\end{cases}"),
      k("|\\square|", "\\left|#0\\right|"),
      k("\\%"),
      k("("),
      k(")"),
    ],
    [
      k("\\dfrac{\\square}{\\square}", "\\frac{#@}{#?}", { size: "sm" }),
      k("\\square^{\\square}", "#@^{#?}"),
      k("\\square_{\\square}", "#@_{#?}"),
      k("["),
      k("]"),
    ],
    [
      k("\\sqrt{\\square}", "\\sqrt{#0}", { variants: [k("\\sqrt[\\square]{\\square}", "\\sqrt[#0]{#?}")] }),
      OVERLINE,
      // 행렬: 누르면 행/열 선택 팝업
      k("\\left(\\begin{smallmatrix}\\square&\\square\\\\\\square&\\square\\end{smallmatrix}\\right)", null, { action: "matrix" }),
      k("\\{", "\\{"),
      k("\\}", "\\}"),
    ],
  ];

  // ── 기호 ──
  const SYMBOLS = [
    [k("\\angle"), Object.assign({}, SQUARE, { variants: [CIRCLE, TRIANGLE] }), PARALLEL, SIMILAR, k("\\equiv")],
    [k("\\perp"), k("/", "/"), k("'", "'"), k(",", ","), k("\\pi")],
    // ∉: \notin 은 MathLive 가 글꼴에 없는 한 글자(U+2209)로 그려 깨지므로 ∈ 에 사선을 긋는 \not\in
    [k("\\in"), k("\\not\\in"), k("\\subset"), k("\\not\\subset"), k("i")],
    [k("\\cup"), k("\\cap"), k("\\varnothing"), k("\\circ"), DEGREE],
    [
      k("\\square^{c}", "#@^{c}"), // 여집합
      k("n(\\square)", "n(#0)"), // 원소의 개수
      k("\\to", "\\to", { variants: [k("\\Rightarrow"), k("\\Leftrightarrow")] }),
      k("\\sim", "\\sim", { variants: [k("\\nsim")] }),
      k("|", "\\mid"),
    ],
  ];

  // ── 대수·미적분 ──
  const CALCULUS = [
    [
      k("\\log\\square", "\\log{#0}", { size: "sm", span: 1.5 }),
      k("\\log_{\\square}\\square", "\\log_{#0}{#?}", { size: "sm", span: 1.5 }),
      k("e", "e", { span: 1.5 }),
      Object.assign({}, DEGREE, { span: 1.5 }),
    ],
    [
      Object.assign({}, SIN, { span: 2, variants: [k("\\csc", "\\csc", { size: "sm" })] }),
      Object.assign({}, COS, { span: 2, variants: [k("\\sec", "\\sec", { size: "sm" })] }),
      Object.assign({}, TAN, { span: 2, variants: [k("\\cot", "\\cot", { size: "sm" })] }),
    ],
    [
      k("\\Sigma", "\\sum_{#0}^{#?}"),
      k("\\lim", "\\lim_{#0\\to#?}", { size: "sm" }),
      k("\\infty"),
      k("\\int", "\\int"),
      k("\\int_{\\square}^{\\square}", "\\int_{#0}^{#?}", { size: "xs" }),
      k("dx", "\\,dx", { size: "sm" }),
    ],
    [
      k("f'(\\square)", "f'(#0)", { size: "sm", span: 2 }),
      k("\\dfrac{dy}{dx}", "\\frac{dy}{dx}", { size: "sm", span: 2 }),
      k("\\Delta", "\\Delta", { span: 2 }),
    ],
    [
      k("{}_{n}\\mathrm{P}_{r}", "{}_{#0}\\mathrm{P}_{#?}", { size: "sm" }),
      k("{}_{n}\\mathrm{C}_{r}", "{}_{#0}\\mathrm{C}_{#?}", { size: "sm" }),
      k("{}_{n}\\Pi_{r}", "{}_{#0}\\Pi_{#?}", { size: "sm" }),
      k("{}_{n}\\mathrm{H}_{r}", "{}_{#0}\\mathrm{H}_{#?}", { size: "sm" }),
      k("!"),
      CDOTS,
    ],
    [
      k("\\mathrm{P}(\\square)", "\\mathrm{P}(#0)", { size: "xs" }),
      k("\\mathrm{P}(\\square|\\square)", "\\mathrm{P}(#0|#?)", { size: "xs" }),
      k("\\mathrm{E}(\\square)", "\\mathrm{E}(#0)", { size: "xs" }),
      k("\\mathrm{V}(\\square)", "\\mathrm{V}(#0)", { size: "xs" }),
      k("\\sigma(\\square)", "\\sigma(#0)", { size: "xs" }),
      k("\\mathrm{N}(\\square,\\square^2)", "\\mathrm{N}(#0,#?^{2})", { size: "xs" }),
    ],
  ];

  // ── 알파벳·그리스 문자 (13칸 기준: 문자 1칸, 넓은 기능 키 3~4칸) ──
  // 키 표시를 실제 입력 모양에 맞춰 대·소문자 모두 기울임으로 그린다 (시안의 대문자 정자체는 따르지 않음)
  const letters = (s) =>
    s.split("").map((c) => k(c, c, { upper: c.toUpperCase(), upperLabel: c.toUpperCase() }));
  // 그리스 문자도 실제 입력 모양에 맞춰 수식 글꼴로 그린다 (시안의 소문자 본문 글꼴은 따르지 않음)
  const GREEK = [
    k("α", "\\alpha"),
    k("β", "\\beta"),
    k("γ", "\\gamma"),
    k("θ", "\\theta"),
    k("σ", "\\sigma"),
    k("μ", "\\mu"),
    k("λ", "\\lambda"),
    k("Δ", "\\Delta"),
    k("Σ", "\\Sigma"),
    k("Ω", "\\Omega"),
  ];
  const ALPHABET = [
    letters("qwertyuiop").concat([fn("backspace", "backspace", { span: 3, align: "end" })]),
    letters("asdfghjkl").concat([fn("enter", "enter", { span: 4, align: "end" })]),
    [fn("shift", "shift", { span: 3, align: "start" })]
      .concat(letters("zxcvbnm"))
      .concat([fn("shift", "shift", { span: 3, align: "end" })]),
    GREEK.concat([{ label: "스페이스", text: true, action: "space", span: 3 }]),
  ];

  // 행렬 크기 선택 범위 (행렬 선택 팝업과 공유)
  const MATRIX_MIN = 1;
  const MATRIX_MAX = 4;
  const clampMatrixSize = (n) => Math.min(MATRIX_MAX, Math.max(MATRIX_MIN, Math.floor(n) || MATRIX_MIN));

  window.MathKeypadLayouts = {
    // 창 폭 (시안 고등 화면 틀)
    width: 1000,
    // rowHeight: 행 높이(px), "fill" 이면 블록 높이를 행 수로 나눠 채움(숫자패드). width: 블록 폭(px, 시안)
    tabs: [
      {
        label: "숫자·연산·기호",
        gap: 8,
        blocks: [
          { rows: OPERATORS, rowHeight: 38, gap: 4, width: 226 },
          { rows: SYMBOLS, rowHeight: 38, gap: 4, width: 226 },
          { rows: CALCULUS, rowHeight: 38, gap: 4, width: 296 },
          { rows: NUMPAD, rowHeight: "fill", gap: 4, width: 148 },
        ],
      },
      {
        label: "알파벳·그리스 문자",
        gap: 0,
        blocks: [{ rows: ALPHABET, rowHeight: 56, gap: 6 }],
      },
    ],
    MATRIX_MIN: MATRIX_MIN,
    MATRIX_MAX: MATRIX_MAX,
    /** a×b 행렬 LaTeX 생성. 첫 칸은 커서(#0), 나머지는 Tab 이동용 빈칸(#?) */
    buildMatrixLatex: function (rows, cols) {
      const body = Array.from({ length: clampMatrixSize(rows) }, (_, i) =>
        Array.from({ length: clampMatrixSize(cols) }, (_, j) => (i === 0 && j === 0 ? "#0" : "#?")).join("&")
      ).join("\\\\");
      return "\\begin{pmatrix}" + body + "\\end{pmatrix}";
    },
  };
})();

// 수식입력기 창 안의 키패드 (프론트 components/math/MathKeypad.vue 의 고등 PC 배치를 옮긴 것)
// new MathKeypad(container, onKey) — onKey(key, upper) 로 누른 키만 알리고, 실제 삽입은 다이얼로그가 한다.
// 키를 눌러도 입력창 포커스를 뺏지 않도록 pointerdown 기본 동작을 막는다.
(function () {
  "use strict";

  const LONG_PRESS_MS = 400;
  const KEY_PADDING = 6; // 라벨 맞춤 시 키 안쪽 여유
  const ICON_DIR = "/images/math-keypad/";
  const ICON_FILE = { left: "arrow-left", right: "arrow-right", enter: "enter", backspace: "delete", shift: "shift" };
  const ARIA = { left: "왼쪽", right: "오른쪽", enter: "줄바꿈", backspace: "지우기", shift: "대문자", space: "스페이스", matrix: "행렬" };

  // 라벨은 프론트(MathView.vue)와 같은 KaTeX 로 그려 모양을 맞춘다. MathLive 정적 렌더는 중괄호·행렬을 다르게 그린다
  const toMarkup = (latex) => window.katex.renderToString(latex, { throwOnError: false });

  // span칸 키 = span개 칸 + 그 사이 간격(span-1개)과 같은 폭이 되도록 basis 에 간격을 더한다
  const flexOf = (span, gap) => span + " " + span + " " + Math.max(0, gap * (span - 1)) + "px";

  class MathKeypad {
    constructor(container, onKey) {
      this.onKey = onKey;
      this.tabs = window.MathKeypadLayouts.tabs;
      this.tabIndex = 0;
      this.upper = false;
      this.popup = null;
      this.pressTimer = null;

      this.root = document.createElement("div");
      this.root.className = "keypad";
      container.appendChild(this.root);

      // 목록 밖을 누르면 닫기 / 창 크기가 바뀌면 라벨 다시 맞춤
      this._onOutside = (ev) => {
        if (this.popup && !this.popup.el.contains(ev.target)) this._closePopup();
      };
      document.addEventListener("pointerdown", this._onOutside, true);
      this._resizeObserver = new ResizeObserver(() => this._fitLabels());

      this.render();
    }

    /** 다이얼로그를 다시 열 때 첫 탭·소문자로 */
    reset() {
      this.tabIndex = 0;
      this.upper = false;
      this._closePopup();
      this.render();
    }

    render() {
      const tab = this.tabs[this.tabIndex];
      this.root.innerHTML = "";

      const tabBar = document.createElement("div");
      tabBar.className = "keypad__tabs";
      tabBar.setAttribute("role", "tablist");
      this.tabs.forEach((t, i) => {
        const b = document.createElement("button");
        b.type = "button";
        b.className = "keypad__tab" + (i === this.tabIndex ? " is-active" : "");
        b.setAttribute("role", "tab");
        b.setAttribute("aria-selected", String(i === this.tabIndex));
        b.textContent = t.label;
        b.addEventListener("pointerdown", (e) => e.preventDefault());
        b.addEventListener("click", () => {
          this.tabIndex = i;
          this.render();
        });
        tabBar.appendChild(b);
      });
      this.root.appendChild(tabBar);

      const body = document.createElement("div");
      body.className = "keypad__body";
      body.style.gap = (tab.gap || 0) + "px";
      tab.blocks.forEach((block) => body.appendChild(this._block(block)));
      this.root.appendChild(body);

      this._resizeObserver.disconnect();
      this._resizeObserver.observe(body);
      requestAnimationFrame(() => this._fitLabels());
    }

    _block(block) {
      const el = document.createElement("div");
      const fill = block.rowHeight === "fill";
      el.className = "keypad__block" + (fill ? " is-fill" : "") + (fill || block.rowHeight >= 56 ? " is-tall" : "");
      el.style.gap = block.gap + "px";
      el.style.flex = block.width ? "0 1 " + block.width + "px" : "1 1 0";
      block.rows.forEach((row) => {
        const r = document.createElement("div");
        r.className = "keypad__row";
        r.style.gap = block.gap + "px";
        if (!fill) r.style.height = block.rowHeight + "px";
        row.forEach((key) => r.appendChild(this._key(key, block.gap)));
        el.appendChild(r);
      });
      return el;
    }

    _key(key, gap) {
      const b = document.createElement("button");
      b.type = "button";
      b.className =
        "keypad__key" +
        (key.fn ? " is-fn" : "") +
        (key.size ? " is-" + key.size : "") +
        (key.align ? " is-" + key.align : "");
      b.style.flex = flexOf(key.span || 1, gap);
      const label = this.upper && key.upperLabel ? key.upperLabel : key.label;
      b.setAttribute("aria-label", ARIA[key.action] || label);

      if (key.icon) {
        const img = document.createElement("img");
        img.className = "keypad__icon is-" + key.icon;
        img.alt = "";
        img.src = ICON_DIR + (key.icon === "shift" && this.upper ? "shift-press" : ICON_FILE[key.icon]) + ".svg";
        b.appendChild(img);
      } else if (key.text) {
        const s = document.createElement("span");
        s.className = "keypad__text";
        s.textContent = label;
        b.appendChild(s);
      } else {
        const s = document.createElement("span");
        s.className = "keypad__label";
        s.innerHTML = toMarkup(label);
        b.appendChild(s);
      }
      if (key.variants) {
        const mark = document.createElement("img");
        mark.className = "keypad__mark";
        mark.alt = "";
        mark.src = ICON_DIR + "variant-mark.svg";
        b.appendChild(mark);
      }
      b.addEventListener("pointerdown", (ev) => this._onKeyDown(ev, key, b));
      return b;
    }

    // ── 누르기 / 길게 누르기 ──
    _press(key) {
      if (key.action === "shift") {
        this.upper = !this.upper;
        this.render();
        return;
      }
      this.onKey(key, this.upper);
    }

    _onKeyDown(ev, key, target) {
      ev.preventDefault();
      this._closePopup();
      this._stopTracking();
      if (key.variants && key.variants.length) {
        this.pressTimer = setTimeout(() => this._openPopup(key, target), LONG_PRESS_MS);
      }
      this._moveHandler = (e) => {
        if (!this.popup) return;
        const i = this._variantIndexAt(e);
        if (i >= 0) this._hover(i);
      };
      // 길게 누른 채 변형 위로 끌어와 놓으면 그 변형 입력. 제자리에서 놓으면 목록을 띄운 채 탭 선택을 기다린다
      this._upHandler = (e) => {
        this._stopTracking();
        if (!this.popup) {
          this._press(key);
          return;
        }
        const i = this._variantIndexAt(e);
        if (i >= 0) this._pick(this.popup.items[i]);
      };
      window.addEventListener("pointermove", this._moveHandler);
      window.addEventListener("pointerup", this._upHandler);
    }

    _stopTracking() {
      clearTimeout(this.pressTimer);
      this.pressTimer = null;
      if (this._moveHandler) window.removeEventListener("pointermove", this._moveHandler);
      if (this._upHandler) window.removeEventListener("pointerup", this._upHandler);
      this._moveHandler = this._upHandler = null;
    }

    _variantIndexAt(ev) {
      const hit = document.elementFromPoint(ev.clientX, ev.clientY);
      const el = hit && hit.closest("[data-variant]");
      return el ? Number(el.dataset.variant) : -1;
    }

    _openPopup(key, target) {
      const r = target.getBoundingClientRect();
      target.classList.add("is-pressed");
      const el = document.createElement("div");
      el.className = "keypad__variants";
      el.style.left = r.left + r.width / 2 + "px";
      el.style.top = r.top - 4 + "px";
      el.addEventListener("pointerdown", (e) => e.preventDefault());
      key.variants.forEach((v, i) => {
        const b = document.createElement("button");
        b.type = "button";
        b.className = "keypad__variant" + (i === 0 ? " is-hover" : ""); // 시안: 첫 변형이 선택된 상태로 뜬다
        b.dataset.variant = String(i);
        b.style.width = r.width + "px";
        b.style.height = Math.min(r.height, 38) + "px";
        const s = document.createElement("span");
        s.className = "keypad__label";
        s.innerHTML = toMarkup(v.label);
        b.appendChild(s);
        b.addEventListener("click", () => this._pick(v));
        el.appendChild(b);
      });
      this.root.appendChild(el);
      this.popup = { el: el, items: key.variants, target: target };
    }

    _hover(i) {
      this.popup.el.querySelectorAll(".keypad__variant").forEach((b, j) => b.classList.toggle("is-hover", i === j));
    }

    _closePopup() {
      if (!this.popup) return;
      this.popup.target.classList.remove("is-pressed");
      this.popup.el.remove();
      this.popup = null;
    }

    _pick(v) {
      this._closePopup();
      this.onKey(v, false);
    }

    // 조밀한 키(N(□,□²)·행렬 등)나 좁은 창에서 라벨이 키보다 넓으면 비율대로 줄여 잘리지 않게 한다
    _fitLabels() {
      this.root.querySelectorAll(".keypad__body .keypad__label").forEach((label) => {
        label.style.transform = "";
        const key = label.parentElement;
        if (!key) return;
        const scale = Math.min(1, (key.clientWidth - KEY_PADDING) / label.offsetWidth);
        if (scale > 0 && scale < 1) label.style.transform = "scale(" + scale + ")";
      });
    }
  }

  window.MathKeypad = MathKeypad;
})();

// 손글씨 수식 드로잉 캔버스 클래스 (의존성 없음, 마우스/터치/펜). (components/math/MathInkCanvas.vue 재작성)
// OCR 인식률 위해 흰 배경 + 검정 펜 고정. container 에 캔버스+버튼을 생성한다.
(function () {
  "use strict";
  const WIDTH = 520;
  const HEIGHT = 280; // 두 줄 손글씨 공간 확보
  const PEN_WIDTH = 3;

  class MathInkCanvas {
    constructor(container) {
      this.strokes = [];
      this.drawing = false;

      const wrap = document.createElement("div");
      wrap.className = "ink-canvas";
      const canvas = document.createElement("canvas");
      canvas.className = "ink-canvas__board";
      canvas.width = WIDTH;
      canvas.height = HEIGHT;
      const actions = document.createElement("div");
      actions.className = "ink-canvas__actions";
      const undoBtn = document.createElement("button");
      undoBtn.type = "button";
      undoBtn.className = "ink-canvas__btn";
      undoBtn.textContent = "한 획 지우기";
      const clearBtn = document.createElement("button");
      clearBtn.type = "button";
      clearBtn.className = "ink-canvas__btn";
      clearBtn.textContent = "전체 지우기";
      actions.append(undoBtn, clearBtn);
      wrap.append(canvas, actions);
      container.appendChild(wrap);

      this.canvas = canvas;
      this.undoBtn = undoBtn;
      this.clearBtn = clearBtn;

      canvas.addEventListener("pointerdown", (e) => this._onDown(e));
      canvas.addEventListener("pointermove", (e) => this._onMove(e));
      canvas.addEventListener("pointerup", () => this._onUp());
      canvas.addEventListener("pointercancel", () => this._onUp());
      canvas.addEventListener("pointerleave", () => this._onUp());
      undoBtn.addEventListener("click", () => this.undo());
      clearBtn.addEventListener("click", () => this.clear());

      this._syncButtons();
      this._redraw();
    }

    _ctx() {
      return this.canvas.getContext("2d");
    }

    _syncButtons() {
      const empty = this.strokes.length === 0;
      this.undoBtn.disabled = empty;
      this.clearBtn.disabled = empty;
    }

    _redraw() {
      const c = this._ctx();
      if (!c) return;
      c.fillStyle = "#fff";
      c.fillRect(0, 0, WIDTH, HEIGHT);
      c.strokeStyle = "#000";
      c.lineWidth = PEN_WIDTH;
      c.lineCap = "round";
      c.lineJoin = "round";
      for (const stroke of this.strokes) {
        if (stroke.length < 2) {
          c.beginPath();
          c.arc(stroke[0].x, stroke[0].y, PEN_WIDTH / 2, 0, Math.PI * 2);
          c.fillStyle = "#000";
          c.fill();
          c.fillStyle = "#fff";
          continue;
        }
        c.beginPath();
        c.moveTo(stroke[0].x, stroke[0].y);
        for (const p of stroke.slice(1)) c.lineTo(p.x, p.y);
        c.stroke();
      }
    }

    _toPoint(ev) {
      const rect = this.canvas.getBoundingClientRect();
      return {
        x: ((ev.clientX - rect.left) / rect.width) * WIDTH,
        y: ((ev.clientY - rect.top) / rect.height) * HEIGHT,
      };
    }

    _onDown(ev) {
      ev.preventDefault();
      this.canvas.setPointerCapture(ev.pointerId);
      this.drawing = true;
      this.strokes.push([this._toPoint(ev)]);
      this._syncButtons();
    }

    _onMove(ev) {
      if (!this.drawing) return;
      const stroke = this.strokes[this.strokes.length - 1];
      stroke.push(this._toPoint(ev));
      const c = this._ctx();
      if (!c || stroke.length < 2) return;
      const prev = stroke[stroke.length - 2];
      const cur = stroke[stroke.length - 1];
      c.strokeStyle = "#000";
      c.lineWidth = PEN_WIDTH;
      c.lineCap = "round";
      c.beginPath();
      c.moveTo(prev.x, prev.y);
      c.lineTo(cur.x, cur.y);
      c.stroke();
    }

    _onUp() {
      if (!this.drawing) return;
      this.drawing = false;
      this._redraw();
    }

    undo() {
      this.strokes.pop();
      this._syncButtons();
      this._redraw();
    }

    clear() {
      this.strokes = [];
      this._syncButtons();
      this._redraw();
    }

    get isEmpty() {
      return this.strokes.length === 0;
    }

    // PNG Blob 추출(OCR 전송용)
    toBlob() {
      return new Promise((resolve) => {
        this.canvas.toBlob((b) => resolve(b), "image/png");
      });
    }

    // 줄 단위 PNG Blob 배열: 스트로크를 Y축 공백으로 클러스터링해 줄별 이미지 생성.
    // 한 줄이면 전체 캔버스 1장(기존 동작과 동일한 강등).
    async toLineBlobs() {
      const clusters = window.InkSeg.clusterStrokesIntoLines(this.strokes);
      if (clusters.length <= 1) {
        const b = await this.toBlob();
        return b ? [b] : [];
      }

      const PAD = 16;
      const blobs = [];
      for (const cluster of clusters) {
        let minX = Infinity;
        let minY = Infinity;
        let maxX = -Infinity;
        let maxY = -Infinity;
        for (const stroke of cluster) {
          for (const p of stroke) {
            if (p.x < minX) minX = p.x;
            if (p.x > maxX) maxX = p.x;
            if (p.y < minY) minY = p.y;
            if (p.y > maxY) maxY = p.y;
          }
        }
        const w = Math.ceil(maxX - minX + PAD * 2);
        const h = Math.ceil(maxY - minY + PAD * 2);
        const offsetX = minX - PAD;
        const offsetY = minY - PAD;

        const off = document.createElement("canvas");
        off.width = w;
        off.height = h;
        const c = off.getContext("2d");
        c.fillStyle = "#fff";
        c.fillRect(0, 0, w, h);
        c.strokeStyle = "#000";
        c.lineWidth = PEN_WIDTH;
        c.lineCap = "round";
        c.lineJoin = "round";
        for (const stroke of cluster) {
          if (stroke.length < 2) {
            c.beginPath();
            c.arc(stroke[0].x - offsetX, stroke[0].y - offsetY, PEN_WIDTH / 2, 0, Math.PI * 2);
            c.fillStyle = "#000";
            c.fill();
            c.fillStyle = "#fff";
            continue;
          }
          c.beginPath();
          c.moveTo(stroke[0].x - offsetX, stroke[0].y - offsetY);
          for (const p of stroke.slice(1)) c.lineTo(p.x - offsetX, p.y - offsetY);
          c.stroke();
        }

        const blob = await new Promise((res) => off.toBlob(res, "image/png"));
        if (blob) blobs.push(blob);
      }
      return blobs;
    }
  }

  window.MathInkCanvas = MathInkCanvas;
})();

