        this._syncInkButtons();
      }

      // [주의] mathModeSpace 는 프로퍼티로만 반영(MathLive 0.110). 값 주입 + 포커스는 다음 틱
      const mf = this.mf;
      if (window.MathConfig) mf.mathModeSpace = window.MathConfig.spaceLatex;
      mf.value = latex || "";
      setTimeout(() => mf.focus(), 0);
    }

    close() {
      this._closeMatrix();
      this.backdrop.style.display = "none";
    }

    _switchTab(next) {
      this.tab = next;
      this.tabs.forEach((t) => t.classList.toggle("is-active", t.getAttribute("data-tab") === next));
      const keyboard = next === "keyboard";
      // math-field 는 탭 전환 시에도 값 유지 위해 display 토글만
      this.keyboardPane.style.display = keyboard ? "" : "none";
      this.inkPane.style.display = keyboard ? "none" : "";
      this.hint.style.display = keyboard ? "" : "none";
      this.inkActions.style.display = keyboard ? "none" : "";
      if (keyboard) setTimeout(() => this.mf.focus(), 0);
    }

    // ── 키패드 입력 ──
    _insert(latex) {
      this.mf.executeCommand(["insert", latex, INSERT_OPTIONS]);
    }

    _onKey(key, upper) {
      const mf = this.mf;
      switch (key.action) {
        case "left":
          mf.executeCommand("moveToPreviousChar");
          break;
        case "right":
          mf.executeCommand("moveToNextChar");
          break;
        case "backspace":
          mf.executeCommand("deleteBackward");
          break;
        case "enter":
          // MathLive 가 \\ 삽입을 멀티라인(\displaylines) 전환으로 처리함 (실측 확인)
          this._insert("\\\\");
          break;
        case "space":
          this._insert(window.MathConfig ? window.MathConfig.spaceLatex : "\\;");
          break;
        case "matrix":
          this._openMatrix();
          break;
        default:
          this._insert(upper && key.upper ? key.upper : key.insert != null ? key.insert : key.label);
      }
    }

    // ── 행렬 ──
    _openMatrix() {
      this.matrix.rows.value = "2";
      this.matrix.cols.value = "2";
      this.matrix.backdrop.style.display = "flex";
      this.matrix.rows.focus();
    }

    _closeMatrix() {
      if (this.matrix.backdrop.style.display === "none") return;
      this.matrix.backdrop.style.display = "none";
      this.mf.focus();
    }

    _insertMatrix() {
      const latex = window.MathKeypadLayouts.buildMatrixLatex(Number(this.matrix.rows.value), Number(this.matrix.cols.value));
      this.matrix.backdrop.style.display = "none";
      this._insert(latex);
    }

    // ── 손글씨 ──
    _syncInkButtons() {
      const empty = !this.ink || this.ink.isEmpty;
      this.inkActions.querySelectorAll("button").forEach((b) => {
        b.disabled = empty;
      });
    }

    // 손글씨를 줄 단위로 분리해 각각 OCR -> 여러 줄이면 gathered 로 결합. 결과는 입력창에도 넣어 키보드 탭에서 이어서 고칠 수 있게 한다
    async _recognize() {
      if (!this.ink || this.ink.isEmpty) return;
      const blobs = await this.ink.toLineBlobs();
      if (!blobs.length) return;

      this.recognizeBtn.textContent = "인식 중...";
      this.recognizeBtn.disabled = true;
      this.errorEl.textContent = "";
      try {
        const results = await Promise.all(
          blobs.map((blob) => {
            const fd = new FormData();
            fd.append("img", blob, "ink.png");
            // FormData 전송 시 Content-Type 미지정(boundary 자동) + CSRF 헤더만 부착
            return fetch(window.MathConfig.ocrEndpoint, {
              method: "POST",
              body: fd,
              headers: window.MathConfig.csrfHeaders(),
            }).then((r) => {
              if (!r.ok) throw new Error("ocr " + r.status);
              return r.json();
            });
          })
        );
        const latexes = results.map((r) => (r.latex || "").trim()).filter(Boolean);
        const merged =
          latexes.length > 1
            ? "\\begin{gathered}" + latexes.join("\\\\ ") + "\\end{gathered}"
            : latexes[0] || "";
        this.mf.value = merged;
        this.resultBox.innerHTML = merged ? window.MathLive.convertLatexToMarkup(merged) : "";
        this.resultBox.classList.toggle("is-filled", !!merged);
      } catch (e) {
        this.errorEl.textContent = "인식에 실패했습니다. OCR 서버 상태를 확인해 주세요.";
      } finally {
        this.recognizeBtn.textContent = "인식하기";
        this._syncInkButtons();
      }
    }

    _confirm() {
      // MathLive 의 \displaylines 는 KaTeX 미지원 -> gathered 로 변환해 방출 (적용은 입력창 값 기준)
      const latex = window.MathCompat.toKatexCompatLatex(this.mf.value || "");
      const cb = this._onConfirm;
      this.close();
      if (cb) cb(latex);
    }

    _cancel() {
      this.close();
    }
  }

  // 싱글톤 접근자: 첫 open 시점에 생성(MathLive <math-field> 정의 이후 보장)
  let instance = null;
  window.MathFieldDialog = {
    get: function () {
      if (!instance) instance = new MathFieldDialogImpl();
      return instance;
    },
  };
})();

// 본문(TinyMCE inline) + 수식(MathLive 다이얼로그) 하이브리드 에디터 팩토리. (components/math/MathRichEditor.vue 재작성)
// 수식 노드 = contenteditable="false" 원자 span/div + data-latex(진실원본) + 내부 KaTeX(표시용).
// TipTap 의 insert/update/onClick 동작을 TinyMCE insertContent/클릭 핸들러로 매핑한다.
// iframe 회피 위해 inline 모드 사용(KaTeX 가 메인 document 에서 렌더되어 크로스도큐먼트 문제 없음).
(function () {
  "use strict";
  const MATH_SELECTOR = '[data-type="inline-math"],[data-type="block-math"]';

  const escAttr = (s) =>
    String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

  // 삽입용 수식 노드 HTML(빈 노드를 KaTeX 로 미리 채워 TinyMCE 가 제거하지 않게)
  function buildMathHtml(latex, isBlock) {
    const tag = isBlock ? "div" : "span";
    const type = isBlock ? "block-math" : "inline-math";
    const cls = isBlock ? "math-node math-block" : "math-node math-inline";
    const html =
      "<" + tag + ' data-type="' + type + '" data-latex="' + escAttr(latex) + '" contenteditable="false" class="' + cls + '"></' + tag + ">";
    return window.MathView.prerenderHtml(html);
  }

  // getContent 결과를 TipTap getHTML 과 의미동치인 깨끗한 HTML 로 정리:
  // 수식 노드는 data-type/data-latex 만 남기고(빈 노드), 에디터 부산물(data-mce-*, bogus) 제거.
  function cleanHtml(rawHtml) {
    const doc = new DOMParser().parseFromString(rawHtml, "text/html");
    doc.querySelectorAll(MATH_SELECTOR).forEach((el) => {
      const isBlock = el.getAttribute("data-type") === "block-math";
      const latex = el.getAttribute("data-latex") || "";
      while (el.firstChild) el.removeChild(el.firstChild);
      Array.prototype.slice.call(el.attributes).forEach((a) => {
        if (a.name !== "data-type" && a.name !== "data-latex") el.removeAttribute(a.name);
      });
      el.setAttribute("data-type", isBlock ? "block-math" : "inline-math");
      el.setAttribute("data-latex", latex);
    });
    doc.querySelectorAll("[data-mce-bogus]").forEach((el) => el.remove());
    doc.body.querySelectorAll("*").forEach((el) => {
      Array.prototype.slice.call(el.attributes).forEach((a) => {
        if (a.name.indexOf("data-mce-") === 0) el.removeAttribute(a.name);
      });
    });
    return doc.body.innerHTML;
  }

  // 에디터 1개 생성. opts: { content, preserveSourceTags, onChange(cleanHtml) }
  function create(targetEl, opts) {
    opts = opts || {};
    const onChange = opts.onChange || function () {};
    const dialog = window.MathFieldDialog.get();
    let editorRef = null;

    const config = {
      target: targetEl,
      inline: true,
      license_key: "gpl",
      base_url: window.MathConfig.tinymceBaseUrl,
      suffix: ".min",
      menubar: false,
      statusbar: false,
      branding: false,
      promotion: false,
      toolbar: "bold italic | mathInline mathBlock",
      plugins: "",
      setup: function (editor) {
        editorRef = editor;
        const renderAll = () => window.MathView.renderAllIn(editor.getBody());
        const emit = () => onChange(cleanHtml(editor.getContent()));

        // CMS 는 학교급과 관계없이 고등 키패드 수식입력기 하나를 쓴다
        const openInsert = (type) =>
          function () {
            dialog.open("", "high", function (latex) {
              if (!latex) return;
              // 신규 삽입 — 여러 줄 수식은 인라인 부적합이므로 블록으로 강제
              const isBlock = type === "block" || window.MathCompat.isMultilineLatex(latex);
              editor.insertContent(buildMathHtml(latex, isBlock));
              renderAll();
              emit();
            });
          };

        editor.ui.registry.addButton("mathInline", { text: "수식", tooltip: "수식 입력", onAction: openInsert("inline") });
        editor.ui.registry.addButton("mathBlock", { text: "블록 수식", tooltip: "블록(가운데) 수식 입력", onAction: openInsert("block") });

        editor.on("init", function () {
          if (opts.content) editor.setContent(window.MathView.prerenderHtml(opts.content));
          renderAll();
          emit();
        });
        editor.on("SetContent", function () {
          renderAll();
        });
        // 수식 노드 클릭 -> 다이얼로그로 수정(data-latex 교체 + 재렌더)
        editor.on("click", function (e) {
          const node = e.target && e.target.closest ? e.target.closest(MATH_SELECTOR) : null;
          if (!node) return;
          dialog.open(node.getAttribute("data-latex") || "", "high", function (latex) {
            if (!latex) return;
            node.setAttribute("data-latex", latex);
            window.MathView.renderNode(node);
            emit();
          });
        });
        editor.on("input change Undo Redo NodeChange", emit);
      },
    };

    if (opts.preserveSourceTags) {
      config.custom_elements = window.MathTinyConfig.custom_elements;
      config.extended_valid_elements = window.MathTinyConfig.extended_valid_elements;
      config.valid_children = window.MathTinyConfig.valid_children;
    } else {
      config.extended_valid_elements = window.MathTinyConfig.mathOnlyValidElements;
    }

    window.tinymce.init(config);

    return {
      // 프로그램적으로 콘텐츠 교체(수식 미리 렌더 후 주입). SetContent 핸들러가 렌더, 이어서 emit.
      setContent: function (html) {
        if (!editorRef) return;
        editorRef.setContent(window.MathView.prerenderHtml(html));
        window.MathView.renderAllIn(editorRef.getBody());
        onChange(cleanHtml(editorRef.getContent()));
      },
      getCleanHtml: function () {
        return editorRef ? cleanHtml(editorRef.getContent()) : "";
      },
    };
  }

  window.MathRichEditor = { create: create };
})();

// 수식 컴포넌트 통합 검증 데모 페이지 와이어링. (pages/math-demo.vue 재작성)
// 4섹션: 하이브리드 에디터 / 단독 답안필드 / KaTeX 렌더 / 샘플 로드·라운드트립.
(function () {
  "use strict";

  const RICH_INIT = "<p>이차방정식의 근의 공식을 수식 버튼으로 삽입해 보세요.</p>";
  const ANSWER_INIT = "x=\\frac{-b\\pm\\sqrt{b^2-4ac}}{2a}";

  const $ = (id) => document.getElementById(id);

  // HTML 에서 수식 노드별 {type, latex} 추출
  function extractMathNodes(html) {
    const doc = new DOMParser().parseFromString(html || "", "text/html");
    const nodes = doc.querySelectorAll('[data-type="inline-math"],[data-type="block-math"]');
    return Array.prototype.slice.call(nodes).map((el) => ({
      type: el.getAttribute("data-type") === "block-math" ? "block" : "inline",
      latex: el.getAttribute("data-latex") || "",
    }));
  }

  // 수식 노드 LaTeX 값 <-> KaTeX 렌더 비교 테이블 생성
  function buildMathNodesTable(host, html, emptyMsg) {
    const nodes = extractMathNodes(html);
    host.innerHTML = "";
    if (!nodes.length) {
      if (emptyMsg) {
        const p = document.createElement("p");
        p.className = "math-demo__empty";
        p.textContent = emptyMsg;
        host.appendChild(p);
      }
      return;
    }
    const table = document.createElement("table");
    table.className = "math-demo__table";
    table.innerHTML =
      "<thead><tr><th>LaTeX 값</th><th>실제 KaTeX 값 (렌더 결과)</th></tr></thead>";
    const tbody = document.createElement("tbody");
    nodes.forEach((n) => {
      const tr = document.createElement("tr");
      const td1 = document.createElement("td");
      const code = document.createElement("code");
      code.textContent = n.latex;
      td1.appendChild(code);
      const td2 = document.createElement("td");
      window.MathView.render(td2, n.latex, n.type === "block");
      tr.append(td1, td2);
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);
    host.appendChild(table);
  }

  // 읽기전용 렌더(MathHtmlView 대체): 수식 노드를 미리 렌더한 HTML 을 그대로 표시
  function renderHtmlView(host, html) {
    host.innerHTML = window.MathView.prerenderHtml(html || "");
  }

  function init() {
    // --- 1. 하이브리드 에디터 ---
    const mathNodes1 = $("mathNodes1");
    const richOut1 = $("richOut1");
    const htmlView1 = $("htmlView1");
    window.MathRichEditor.create($("mre1"), {
      content: RICH_INIT,
      onChange: function (html) {
        richOut1.textContent = html;
        buildMathNodesTable(mathNodes1, html, "에디터에 삽입된 수식이 없습니다.");
        renderHtmlView(htmlView1, html);
      },
    });

    // --- 2. 단독 답안 입력 + 3. 렌더 전용 ---
    const af = $("answerField");
    const answerLatexOut = $("answerLatexOut");
    const mathView3 = $("mathView3");
    const updateAnswer = (latex) => {
      answerLatexOut.textContent = latex;
      window.MathView.render(mathView3, latex, true);
    };
    const answerPlaceholder = $("answerPlaceholder");
    if (af) {
      af.addEventListener("input", () => updateAnswer(af.value));
      af.value = ANSWER_INIT;
      // placeholder 는 LaTeX 문자열(한글은 \text{} 로 감쌀 것). attribute 가 아니라
      // 프로퍼티로 대입해야 반영된다 (MathLive 0.110)
      if (answerPlaceholder) {
        af.placeholder = answerPlaceholder.value;
        answerPlaceholder.addEventListener("input", () => {
          af.placeholder = answerPlaceholder.value;
        });
      }
    }
    updateAnswer(ANSWER_INIT);

    // --- 4. 실제 문제 로드 -> 편집 -> 라운드트립 ---
    const blockSelect = $("blockSelect");
    const sourceText = $("sourceText");
    const sourceOut = $("sourceOut");
    const convertedOut = $("convertedOut");
    const loadedOut = $("loadedOut");
    const savedOut = $("savedOut");
    const loadedMathNodes = $("loadedMathNodes");
    const htmlView4 = $("htmlView4");

    const editor4 = window.MathRichEditor.create($("mre4"), {
      preserveSourceTags: true,
      onChange: function (html) {
        loadedOut.textContent = html || "(미로드)";
        savedOut.textContent = window.MathRoundtrip.htmlToLatexDelimiters(html) || "(미로드)";
        buildMathNodesTable(loadedMathNodes, html, "");
        renderHtmlView(htmlView4, html);
      },
    });

    const ROLE_LABEL = { question: "문제", answer: "정답", explanation: "해설" };
    const syncSource = (text) => {
      sourceText.value = text || "";
      sourceOut.textContent = text || "";
    };

    // 샘플 로드(static fetch). content.blocks 를 역할별 셀렉트로
    fetch(window.MathConfig.samplesUrl)
      .then((r) => r.json())
      .then((data) => {
        const blocks = (data.content && data.content.blocks) || [];
        blockSelect.innerHTML = "";
        blocks.forEach((b) => {
          const opt = document.createElement("option");
          opt.value = b.blockId;
          opt.textContent = ROLE_LABEL[b.role] || b.role;
          opt.dataset.text = b.text || "";
          blockSelect.appendChild(opt);
        });
        if (blocks.length) syncSource(blocks[0].text || "");
      })
      .catch(() => {
        sourceOut.textContent = "(샘플 로드 실패)";
      });

    blockSelect.addEventListener("change", function () {
      const opt = blockSelect.selectedOptions[0];
      if (opt) syncSource(opt.dataset.text || "");
    });
    sourceText.addEventListener("input", function () {
      sourceOut.textContent = sourceText.value;
    });

    $("loadBtn").addEventListener("click", function () {
      const converted = window.MathRoundtrip.latexDelimitersToHtml(sourceText.value);
      convertedOut.textContent = converted || "(변환 결과 없음)";
      editor4.setContent(converted);
    });
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init);
  else init();
})();
